-- Generated by build.py from assessments/*.json. Run schema.sql first. Safe to run again: it replaces the questions.

insert into public.assessments (slug, title, pass_pct, questions) values ('business-growth', $q$Business Growth: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "A brewer buys a chain of pubs. This is:", "opts": ["Backward vertical integration", "Forward vertical integration", "Horizontal integration", "Conglomerate integration"], "ans": "1", "marks": 1, "topic": "Integration", "ok": "Correct: Pubs are nearer the consumer, so it is forward vertical integration.", "fb": "Pubs are nearer the consumer, so it is forward vertical integration. Review the Learn tab.", "model": "Forward vertical integration"}, {"id": "q2", "type": "mcq", "q": "A bakery chain buys a flour mill. This is:", "opts": ["Forward vertical integration", "Backward vertical integration", "Horizontal integration", "Organic growth"], "ans": "1", "marks": 1, "topic": "Integration", "ok": "Correct: Millers are suppliers, nearer the raw materials.", "fb": "Millers are suppliers, nearer the raw materials. Review the Learn tab.", "model": "Backward vertical integration"}, {"id": "q3", "type": "mcq", "q": "Two supermarket chains merge. This is:", "opts": ["Horizontal integration", "Conglomerate integration", "Forward vertical integration", "Backward vertical integration"], "ans": "0", "marks": 1, "topic": "Integration", "ok": "Correct: They operate at the same stage in the same industry.", "fb": "They operate at the same stage in the same industry. Review the Learn tab.", "model": "Horizontal integration"}, {"id": "q4", "type": "mcq", "q": "A food company buys a software firm. This is:", "opts": ["Horizontal integration", "Vertical integration", "Conglomerate integration", "Organic growth"], "ans": "2", "marks": 1, "topic": "Integration", "ok": "Correct: The industries are unrelated.", "fb": "The industries are unrelated. Review the Learn tab.", "model": "Conglomerate integration"}, {"id": "q5", "type": "mcq", "q": "The principal-agent problem arises because:", "opts": ["Shareholders manage the firm", "Managers and shareholders may have different objectives", "Firms cannot make a profit", "Competition law forbids growth"], "ans": "1", "marks": 1, "topic": "Principal-agent", "ok": "Correct: Owners and managers can want different things, and managers know more.", "fb": "Owners and managers can want different things, and managers know more. Review the Learn tab.", "model": "Managers and shareholders may have different objectives"}, {"id": "q6", "type": "mcq", "q": "Which is a constraint on business growth?", "opts": ["A rapidly growing market", "Easy access to finance", "An owner who wants to keep control", "Economies of scale"], "ans": "2", "marks": 1, "topic": "Constraints", "ok": "Correct: Owner objectives can limit growth.", "fb": "Owner objectives can limit growth. Review the Learn tab.", "model": "An owner who wants to keep control"}, {"id": "q7", "type": "mcq", "q": "A charity that reinvests its surplus is best described as:", "opts": ["Public sector", "Not-for-profit", "A monopoly", "Conglomerate"], "ans": "1", "marks": 1, "topic": "Types of firm", "ok": "Correct: It is private-sector but not-for-profit.", "fb": "It is private-sector but not-for-profit. Review the Learn tab.", "model": "Not-for-profit"}, {"id": "q8", "type": "mcq", "q": "Which is a likely reason for a demerger?", "opts": ["To gain economies of scale", "To refocus on the core business", "To remove a competitor", "To increase diversification"], "ans": "1", "marks": 1, "topic": "Demergers", "ok": "Correct: Demergers often follow lost focus or diseconomies of scale.", "fb": "Demergers often follow lost focus or diseconomies of scale. Review the Learn tab.", "model": "To refocus on the core business"}, {"id": "q9", "type": "mcq", "q": "Which is an advantage of organic growth over a takeover?", "opts": ["It is faster", "It is usually lower risk and keeps control and culture", "It always removes a rival", "It needs large external finance"], "ans": "1", "marks": 1, "topic": "Growth methods", "ok": "Correct: Organic growth is gradual, lower risk, and avoids integration problems.", "fb": "Organic growth is gradual, lower risk, and avoids integration problems. Review the Learn tab.", "model": "It is usually lower risk and keeps control and culture"}, {"id": "q10", "type": "mcq", "q": "Which would reduce the principal-agent problem?", "opts": ["Paying managers a fixed salary regardless of results", "Linking manager pay to profit or share price", "Reducing audits", "Hiding accounts from shareholders"], "ans": "1", "marks": 1, "topic": "Principal-agent", "ok": "Correct: Performance-linked pay aligns manager and shareholder interests.", "fb": "Performance-linked pay aligns manager and shareholder interests. Review the Learn tab.", "model": "Linking manager pay to profit or share price"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('government-intervention-competition', $q$Government Intervention: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "CPI − X regulation is a form of:", "opts": ["Merger control", "Price regulation", "Nationalisation", "Deregulation"], "ans": "1", "marks": 1, "topic": "Regulation", "ok": "Correct: It limits price rises set by a regulator.", "fb": "It limits price rises set by a regulator. Review the Learn tab.", "model": "Price regulation"}, {"id": "q2", "type": "mcq", "q": "A potential drawback of price caps is:", "opts": ["Higher prices", "Firms may cut quality", "More monopoly power", "Less competition for contracts"], "ans": "1", "marks": 1, "topic": "Regulation", "ok": "Correct: Firms may protect profit by cutting costs, including quality.", "fb": "Firms may protect profit by cutting costs, including quality. Review the Learn tab.", "model": "Firms may cut quality"}, {"id": "q3", "type": "mcq", "q": "Regulatory capture occurs when:", "opts": ["A regulator is too strict", "A regulator favours the industry it regulates", "A firm leaves a market", "Competition increases"], "ans": "1", "marks": 1, "topic": "Limits", "ok": "Correct: The regulator acts in the interests of firms.", "fb": "The regulator acts in the interests of firms. Review the Learn tab.", "model": "A regulator favours the industry it regulates"}, {"id": "q4", "type": "mcq", "q": "Which is an example of deregulation?", "opts": ["Introducing a price cap", "Removing licensing requirements to enter a market", "Nationalising a railway", "Blocking a merger"], "ans": "1", "marks": 1, "topic": "Competition", "ok": "Correct: It lowers barriers to entry.", "fb": "It lowers barriers to entry. Review the Learn tab.", "model": "Removing licensing requirements to enter a market"}, {"id": "q5", "type": "mcq", "q": "Competitive tendering means:", "opts": ["Selling public firms to shareholders", "Firms bidding for contracts to deliver services", "Capping prices", "Regulating profit"], "ans": "1", "marks": 1, "topic": "Competition", "ok": "Correct: Competition for the contract.", "fb": "Competition for the contract. Review the Learn tab.", "model": "Firms bidding for contracts to deliver services"}, {"id": "q6", "type": "mcq", "q": "Nationalisation involves:", "opts": ["Selling a firm to the private sector", "Government ownership of a firm", "Breaking up a monopoly", "A price cap"], "ans": "1", "marks": 1, "topic": "Ownership", "ok": "Correct: The state takes ownership.", "fb": "The state takes ownership. Review the Learn tab.", "model": "Government ownership of a firm"}, {"id": "q7", "type": "mcq", "q": "Asymmetric information limits regulation because:", "opts": ["Firms know more about their costs than the regulator", "Regulators know more than firms", "Consumers know everything", "Prices are fixed"], "ans": "0", "marks": 1, "topic": "Limits", "ok": "Correct: The regulator may set the cap too high or too low.", "fb": "The regulator may set the cap too high or too low. Review the Learn tab.", "model": "Firms know more about their costs than the regulator"}, {"id": "q8", "type": "num", "q": "A regulator caps price rises at CPI − X. CPI is 4% and X is 1.5%. By what percentage may the price rise?", "ans": 2.5, "tol": 0.01, "marks": 1, "topic": "Price cap", "hint": "Enter a number.", "ok": "Correct: 4 − 1.5 = 2.5%.", "fb": "4 − 1.5 = 2.5%. Check the worked examples.", "model": "2.5"}, {"id": "q9", "type": "num", "q": "The price is £200 and may rise by CPI − X = 3%. Calculate the maximum new price (£).", "ans": 206, "tol": 0.1, "marks": 1, "topic": "Price cap", "hint": "Enter a number.", "ok": "Correct: 200 × 1.03 = £206.", "fb": "200 × 1.03 = £206. Check the worked examples.", "model": "206"}, {"id": "q10", "type": "num", "q": "A natural monopoly sells 20 units at £4 with average cost £4. Calculate profit (£).", "ans": 0, "tol": 0.01, "marks": 1, "topic": "Regulation", "hint": "Enter a number.", "ok": "Correct: (4 − 4) × 20 = £0, normal profit.", "fb": "(4 − 4) × 20 = £0, normal profit. Check the worked examples.", "model": "0"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('labour-market', $q$The Labour Market: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "Demand for labour is a derived demand because it depends on:", "opts": ["The wage rate only", "Demand for the product workers produce", "Government spending", "Union power"], "ans": "1", "marks": 1, "topic": "Demand for labour", "ok": "Correct: Firms hire labour to produce goods and services people want.", "fb": "Firms hire labour to produce goods and services people want. Review the Learn tab.", "model": "Demand for the product workers produce"}, {"id": "q2", "type": "mcq", "q": "MRP is calculated as:", "opts": ["MPP ÷ MR", "MPP × MR", "Wage × employment", "Price ÷ MPP"], "ans": "1", "marks": 1, "topic": "Demand for labour", "ok": "Correct: MRP = marginal physical product × marginal revenue.", "fb": "MRP = marginal physical product × marginal revenue. Review the Learn tab.", "model": "MPP × MR"}, {"id": "q3", "type": "mcq", "q": "Which would shift the demand for labour to the right?", "opts": ["Higher wages", "A rise in demand for the product", "More migration", "Longer training"], "ans": "1", "marks": 1, "topic": "Demand for labour", "ok": "Correct: Derived demand rises with product demand.", "fb": "Derived demand rises with product demand. Review the Learn tab.", "model": "A rise in demand for the product"}, {"id": "q4", "type": "mcq", "q": "Demand for labour is likely to be less elastic when:", "opts": ["Labour is a large share of costs", "Capital is a close substitute", "Labour is a small share of costs", "The time period is long"], "ans": "2", "marks": 1, "topic": "Elasticity", "ok": "Correct: A wage rise then has little effect on total costs.", "fb": "A wage rise then has little effect on total costs. Review the Learn tab.", "model": "Labour is a small share of costs"}, {"id": "q5", "type": "mcq", "q": "A minimum wage set above equilibrium in a competitive market causes:", "opts": ["A shortage of labour", "A surplus of labour", "No change", "Lower labour supply"], "ans": "1", "marks": 1, "topic": "Minimum wage", "ok": "Correct: Quantity supplied exceeds quantity demanded.", "fb": "Quantity supplied exceeds quantity demanded. Review the Learn tab.", "model": "A surplus of labour"}, {"id": "q6", "type": "mcq", "q": "Geographical immobility is most likely caused by:", "opts": ["Skills mismatch", "High house prices in job-rich areas", "A lack of qualifications", "Automation"], "ans": "1", "marks": 1, "topic": "Immobility", "ok": "Correct: House prices and family ties stop people moving.", "fb": "House prices and family ties stop people moving. Review the Learn tab.", "model": "High house prices in job-rich areas"}, {"id": "q7", "type": "mcq", "q": "A policy to reduce occupational immobility is:", "opts": ["Raising the minimum wage", "Retraining and apprenticeship schemes", "Cutting housing supply", "Raising interest rates"], "ans": "1", "marks": 1, "topic": "Immobility", "ok": "Correct: It builds the skills needed to change jobs.", "fb": "It builds the skills needed to change jobs. Review the Learn tab.", "model": "Retraining and apprenticeship schemes"}, {"id": "q8", "type": "num", "q": "A worker's marginal physical product is 5 units and each unit sells for £8 (price taker). Calculate MRP (£).", "ans": 40, "tol": 0.1, "marks": 1, "topic": "MRP", "hint": "Enter a number.", "ok": "Correct: MRP = MPP × MR = 5 × 8 = £40.", "fb": "MRP = MPP × MR = 5 × 8 = £40. Check the worked examples.", "model": "40"}, {"id": "q9", "type": "num", "q": "Wage rises by 10% and employment falls by 5%. Calculate the elasticity of demand for labour (ignore the sign).", "ans": 0.5, "tol": 0.01, "marks": 1, "topic": "Elasticity", "hint": "Enter a number.", "ok": "Correct: 5 ÷ 10 = 0.5.", "fb": "5 ÷ 10 = 0.5. Check the worked examples.", "model": "0.5"}, {"id": "q10", "type": "num", "q": "Employment falls from 80 to 60 after a wage floor is introduced. Calculate the percentage fall in employment.", "ans": 25, "tol": 0.1, "marks": 1, "topic": "Minimum wage", "hint": "Enter a number.", "ok": "Correct: 20 ÷ 80 × 100 = 25%.", "fb": "20 ÷ 80 × 100 = 25%. Check the worked examples.", "model": "25"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('monopoly-price-discrimination', $q$Monopoly and Price Discrimination: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "A monopolist maximises profit where:", "opts": ["P = MC", "MC = MR", "MR = 0", "AC is at its minimum"], "ans": "1", "marks": 1, "topic": "Equilibrium", "ok": "Correct: Profit is maximised where MC = MR.", "fb": "Profit is maximised where MC = MR. Review the Learn tab.", "model": "MC = MR"}, {"id": "q2", "type": "mcq", "q": "For a monopolist the price is read from:", "opts": ["MR", "MC", "AR (the demand curve)", "AC"], "ans": "2", "marks": 1, "topic": "Equilibrium", "ok": "Correct: Go up from the output to the AR curve.", "fb": "Go up from the output to the AR curve. Review the Learn tab.", "model": "AR (the demand curve)"}, {"id": "q3", "type": "mcq", "q": "The deadweight loss of monopoly is:", "opts": ["Supernormal profit", "The welfare lost because output is below the competitive level", "Producer surplus", "The area under MC"], "ans": "1", "marks": 1, "topic": "Efficiency", "ok": "Correct: It is the triangle of welfare no one receives.", "fb": "It is the triangle of welfare no one receives. Review the Learn tab.", "model": "The welfare lost because output is below the competitive level"}, {"id": "q4", "type": "mcq", "q": "Which is a condition for price discrimination?", "opts": ["Perfect competition", "The same elasticity in every group", "The ability to prevent resale", "Falling costs"], "ans": "2", "marks": 1, "topic": "Price discrimination", "ok": "Correct: Otherwise low-price buyers could resell to high-price buyers.", "fb": "Otherwise low-price buyers could resell to high-price buyers. Review the Learn tab.", "model": "The ability to prevent resale"}, {"id": "q5", "type": "mcq", "q": "In third-degree price discrimination the group with less elastic demand is charged:", "opts": ["A lower price", "A higher price", "The same price", "Marginal cost"], "ans": "1", "marks": 1, "topic": "Price discrimination", "ok": "Correct: Less elastic buyers respond less to price, so a higher price raises revenue.", "fb": "Less elastic buyers respond less to price, so a higher price raises revenue. Review the Learn tab.", "model": "A higher price"}, {"id": "q6", "type": "mcq", "q": "A natural monopoly exists where:", "opts": ["Firms collude", "LRAC falls over the whole range of market demand", "The government owns the firm", "There are many small firms"], "ans": "1", "marks": 1, "topic": "Natural monopoly", "ok": "Correct: Economies of scale are so large one firm is cheapest.", "fb": "Economies of scale are so large one firm is cheapest. Review the Learn tab.", "model": "LRAC falls over the whole range of market demand"}, {"id": "q7", "type": "mcq", "q": "Which is a possible benefit of monopoly?", "opts": ["Lower output", "Economies of scale and R&D funded by supernormal profit", "Deadweight loss", "X-inefficiency"], "ans": "1", "marks": 1, "topic": "Costs and benefits", "ok": "Correct: Scale economies and dynamic efficiency.", "fb": "Scale economies and dynamic efficiency. Review the Learn tab.", "model": "Economies of scale and R&D funded by supernormal profit"}, {"id": "q8", "type": "num", "q": "A monopolist sells 50 units at £30 each with average cost of £22. Calculate supernormal profit (£).", "ans": 400, "tol": 0.5, "marks": 1, "topic": "Profit", "hint": "Enter a number.", "ok": "Correct: (30 − 22) × 50 = £400.", "fb": "(30 − 22) × 50 = £400. Check the worked examples.", "model": "400"}, {"id": "q9", "type": "num", "q": "A cinema sells 200 adult tickets at £10 and 150 student tickets at £6. Calculate total revenue (£).", "ans": 2900, "tol": 0.5, "marks": 1, "topic": "Revenue", "hint": "Enter a number.", "ok": "Correct: 2,000 + 900 = £2,900.", "fb": "2,000 + 900 = £2,900. Check the worked examples.", "model": "2900"}, {"id": "q10", "type": "num", "q": "A monopolist faces MR = 20 − 4Q. Calculate MR at Q = 3 (£).", "ans": 8, "tol": 0.1, "marks": 1, "topic": "Revenue", "hint": "Enter a number.", "ok": "Correct: MR = 20 − 12 = £8.", "fb": "MR = 20 − 12 = £8. Check the worked examples.", "model": "8"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('monopsony-contestability', $q$Monopsony and Contestability: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "A monopsony is a market with:", "opts": ["One seller", "One dominant buyer", "Two sellers", "Many buyers and sellers"], "ans": "1", "marks": 1, "topic": "Monopsony", "ok": "Correct: A single or dominant buyer.", "fb": "A single or dominant buyer. Review the Learn tab.", "model": "One dominant buyer"}, {"id": "q2", "type": "mcq", "q": "A monopsony employer hires workers up to the point where:", "opts": ["MRP = supply", "MCL = MRP", "MR = MC", "MRP = 0"], "ans": "1", "marks": 1, "topic": "Monopsony", "ok": "Correct: It equates marginal cost of labour with marginal revenue product.", "fb": "It equates marginal cost of labour with marginal revenue product. Review the Learn tab.", "model": "MCL = MRP"}, {"id": "q3", "type": "mcq", "q": "Compared with a competitive labour market, a monopsony employer pays:", "opts": ["A higher wage and employs more", "A lower wage and employs fewer", "A lower wage and employs more", "The same wage"], "ans": "1", "marks": 1, "topic": "Monopsony", "ok": "Correct: It restricts employment and pays the supply-curve wage.", "fb": "It restricts employment and pays the supply-curve wage. Review the Learn tab.", "model": "A lower wage and employs fewer"}, {"id": "q4", "type": "mcq", "q": "A minimum wage between the monopsony wage and the competitive wage is likely to:", "opts": ["Reduce employment", "Increase wages and employment", "Have no effect", "Reduce wages"], "ans": "1", "marks": 1, "topic": "Minimum wage", "ok": "Correct: MCL becomes flat at the minimum wage until the supply curve.", "fb": "MCL becomes flat at the minimum wage until the supply curve. Review the Learn tab.", "model": "Increase wages and employment"}, {"id": "q5", "type": "mcq", "q": "Sunk costs are:", "opts": ["All production costs", "Costs that cannot be recovered when a firm leaves the market", "Fixed costs only", "Marginal costs"], "ans": "1", "marks": 1, "topic": "Contestability", "ok": "Correct: Spent and unrecoverable.", "fb": "Spent and unrecoverable. Review the Learn tab.", "model": "Costs that cannot be recovered when a firm leaves the market"}, {"id": "q6", "type": "mcq", "q": "Which makes a market more contestable?", "opts": ["High sunk costs", "Strong brand loyalty", "Low barriers to entry and exit", "Patents"], "ans": "2", "marks": 1, "topic": "Contestability", "ok": "Correct: Low barriers allow hit-and-run entry.", "fb": "Low barriers allow hit-and-run entry. Review the Learn tab.", "model": "Low barriers to entry and exit"}, {"id": "q7", "type": "mcq", "q": "In a contestable market incumbents are likely to:", "opts": ["Raise prices", "Keep price close to average cost", "Reduce output", "Ignore rivals"], "ans": "1", "marks": 1, "topic": "Contestability", "ok": "Correct: To deter entry.", "fb": "To deter entry. Review the Learn tab.", "model": "Keep price close to average cost"}, {"id": "q8", "type": "mcq", "q": "Which is a strategic barrier to entry?", "opts": ["A patent", "Economies of scale", "Predatory pricing", "A government licence"], "ans": "2", "marks": 1, "topic": "Barriers", "ok": "Correct: Behaviour by incumbents designed to deter entry.", "fb": "Behaviour by incumbents designed to deter entry. Review the Learn tab.", "model": "Predatory pricing"}, {"id": "q9", "type": "num", "q": "MRP = 20 − 0.1L. Calculate MRP when 50 workers are employed (£).", "ans": 15, "tol": 0.01, "marks": 1, "topic": "Labour market", "hint": "Enter a number.", "ok": "Correct: 20 − 5 = £15.", "fb": "20 − 5 = £15. Check the worked examples.", "model": "15"}, {"id": "q10", "type": "num", "q": "MCL = 4 + 0.2L. Calculate the marginal cost of labour at 50 workers (£).", "ans": 14, "tol": 0.01, "marks": 1, "topic": "Labour market", "hint": "Enter a number.", "ok": "Correct: 4 + 10 = £14.", "fb": "4 + 10 = £14. Check the worked examples.", "model": "14"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('oligopoly', $q$Oligopoly: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "Which is a key characteristic of oligopoly?", "opts": ["Many small firms", "Interdependence between firms", "No barriers to entry", "A single seller"], "ans": "1", "marks": 1, "topic": "Characteristics", "ok": "Correct: Each firm's decisions depend on how rivals react.", "fb": "Each firm's decisions depend on how rivals react. Review the Learn tab.", "model": "Interdependence between firms"}, {"id": "q2", "type": "mcq", "q": "The three-firm concentration ratio adds together:", "opts": ["The three smallest shares", "The three largest shares", "All market shares", "The profits of three firms"], "ans": "1", "marks": 1, "topic": "Concentration", "ok": "Correct: It is the combined market share of the three largest firms.", "fb": "It is the combined market share of the three largest firms. Review the Learn tab.", "model": "The three largest shares"}, {"id": "q3", "type": "mcq", "q": "A cartel is:", "opts": ["A merger of two firms", "A formal agreement between firms to fix price or output", "A type of price war", "A government regulator"], "ans": "1", "marks": 1, "topic": "Collusion", "ok": "Correct: This is overt collusion.", "fb": "This is overt collusion. Review the Learn tab.", "model": "A formal agreement between firms to fix price or output"}, {"id": "q4", "type": "mcq", "q": "In the prisoner's dilemma, firms end up cheating because:", "opts": ["Cheating is the dominant strategy", "Cheating is legal", "Cheating raises the price", "Firms cannot calculate profits"], "ans": "0", "marks": 1, "topic": "Game theory", "ok": "Correct: Cheating pays whatever the rival does.", "fb": "Cheating pays whatever the rival does. Review the Learn tab.", "model": "Cheating is the dominant strategy"}, {"id": "q5", "type": "mcq", "q": "Pricing below cost to force a rival out is:", "opts": ["Limit pricing", "Predatory pricing", "Price leadership", "Tacit collusion"], "ans": "1", "marks": 1, "topic": "Pricing", "ok": "Correct: Predatory pricing aims to eliminate a competitor.", "fb": "Predatory pricing aims to eliminate a competitor. Review the Learn tab.", "model": "Predatory pricing"}, {"id": "q6", "type": "mcq", "q": "Which is non-price competition?", "opts": ["A price war", "Advertising and branding", "Predatory pricing", "Price fixing"], "ans": "1", "marks": 1, "topic": "Competition", "ok": "Correct: Branding, advertising, quality and service.", "fb": "Branding, advertising, quality and service. Review the Learn tab.", "model": "Advertising and branding"}, {"id": "q7", "type": "mcq", "q": "Which makes collusion harder to sustain?", "opts": ["Few firms", "Strong barriers to entry", "Many firms with different costs", "Similar products"], "ans": "2", "marks": 1, "topic": "Collusion", "ok": "Correct: Agreement is harder with more, different firms.", "fb": "Agreement is harder with more, different firms. Review the Learn tab.", "model": "Many firms with different costs"}, {"id": "q8", "type": "num", "q": "Four largest firms have market shares of 30%, 25%, 15% and 10%. Calculate CR4 (%).", "ans": 80, "tol": 0.1, "marks": 1, "topic": "Concentration", "hint": "Enter a number.", "ok": "Correct: 30 + 25 + 15 + 10 = 80%.", "fb": "30 + 25 + 15 + 10 = 80%. Check the worked examples.", "model": "80"}, {"id": "q9", "type": "num", "q": "Shares of the five largest firms: 25%, 20%, 15%, 12% and 10%. Calculate CR3 (%).", "ans": 60, "tol": 0.1, "marks": 1, "topic": "Concentration", "hint": "Enter a number.", "ok": "Correct: 25 + 20 + 15 = 60%.", "fb": "25 + 20 + 15 = 60%. Check the worked examples.", "model": "60"}, {"id": "q10", "type": "num", "q": "Two colluding firms each produce 50 units and sell at £12 with marginal cost £4. Calculate each firm's profit (£).", "ans": 400, "tol": 0.5, "marks": 1, "topic": "Collusion", "hint": "Enter a number.", "ok": "Correct: (12 − 4) × 50 = £400.", "fb": "(12 − 4) × 50 = £400. Check the worked examples.", "model": "400"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('perfect-monopolistic-competition', $q$Perfect and Monopolistic Competition: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "Allocative efficiency is achieved where:", "opts": ["MC = AC", "P = MC", "TR is maximised", "AC is at its minimum"], "ans": "1", "marks": 1, "topic": "Efficiency", "ok": "Correct: Allocative efficiency occurs where price equals marginal cost.", "fb": "Allocative efficiency occurs where price equals marginal cost. Review the Learn tab.", "model": "P = MC"}, {"id": "q2", "type": "mcq", "q": "Productive efficiency occurs where:", "opts": ["P = MC", "Output is at the lowest point of AC", "MR = 0", "Profit is zero"], "ans": "1", "marks": 1, "topic": "Efficiency", "ok": "Correct: Productive efficiency is at minimum average cost, where MC = AC.", "fb": "Productive efficiency is at minimum average cost, where MC = AC. Review the Learn tab.", "model": "Output is at the lowest point of AC"}, {"id": "q3", "type": "mcq", "q": "A perfectly competitive firm faces a demand curve that is:", "opts": ["Downward-sloping", "Perfectly inelastic", "Horizontal at the market price", "Kinked"], "ans": "2", "marks": 1, "topic": "Perfect competition", "ok": "Correct: It is a price taker, so AR = MR = P.", "fb": "It is a price taker, so AR = MR = P. Review the Learn tab.", "model": "Horizontal at the market price"}, {"id": "q4", "type": "mcq", "q": "In the long run a perfectly competitive firm earns:", "opts": ["Supernormal profit", "Normal profit", "A permanent loss", "Maximum revenue"], "ans": "1", "marks": 1, "topic": "Perfect competition", "ok": "Correct: Entry removes supernormal profit.", "fb": "Entry removes supernormal profit. Review the Learn tab.", "model": "Normal profit"}, {"id": "q5", "type": "mcq", "q": "In long-run equilibrium in monopolistic competition:", "opts": ["P = MC", "AR is tangent to AC", "Supernormal profit is earned", "Output is at minimum AC"], "ans": "1", "marks": 1, "topic": "Monopolistic competition", "ok": "Correct: AR touches AC at one point, so only normal profit is earned.", "fb": "AR touches AC at one point, so only normal profit is earned. Review the Learn tab.", "model": "AR is tangent to AC"}, {"id": "q6", "type": "mcq", "q": "X-inefficiency refers to:", "opts": ["Producing at minimum AC", "Costs above those necessary for a given output", "Efficiency over time", "Charging P = MC"], "ans": "1", "marks": 1, "topic": "Efficiency", "ok": "Correct: Lack of competitive pressure allows slack.", "fb": "Lack of competitive pressure allows slack. Review the Learn tab.", "model": "Costs above those necessary for a given output"}, {"id": "q7", "type": "mcq", "q": "Which is a characteristic of monopolistic competition?", "opts": ["Homogeneous products", "High barriers to entry", "Differentiated products", "A single seller"], "ans": "2", "marks": 1, "topic": "Monopolistic competition", "ok": "Correct: Branding and differentiation give some price-setting power.", "fb": "Branding and differentiation give some price-setting power. Review the Learn tab.", "model": "Differentiated products"}, {"id": "q8", "type": "num", "q": "A firm sells 400 units at £5 each. Average cost is £4.20. Calculate total profit (£).", "ans": 320, "tol": 0.5, "marks": 1, "topic": "Profit", "hint": "Enter a number.", "ok": "Correct: (5 − 4.20) × 400 = £320.", "fb": "(5 − 4.20) × 400 = £320. Check the worked examples.", "model": "320"}, {"id": "q9", "type": "num", "q": "A firm sells 50 units at £12 each and has average cost of £9. Calculate total profit (£).", "ans": 150, "tol": 0.5, "marks": 1, "topic": "Profit", "hint": "Enter a number.", "ok": "Correct: (12 − 9) × 50 = £150.", "fb": "(12 − 9) × 50 = £150. Check the worked examples.", "model": "150"}, {"id": "q10", "type": "num", "q": "A monopolistically competitive firm sells 120 units at £10 with AC of £8. Calculate supernormal profit (£).", "ans": 240, "tol": 0.5, "marks": 1, "topic": "Profit", "hint": "Enter a number.", "ok": "Correct: (10 − 8) × 120 = £240.", "fb": "(10 − 8) × 120 = £240. Check the worked examples.", "model": "240"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('revenue-costs-profits', $q$Objectives, Revenues, Costs and Profits: assessment$q$, 70, $q$[{"id": "q1", "type": "mcq", "q": "For a firm facing a downward-sloping demand curve, MR is:", "opts": ["Equal to AR", "Below AR", "Above AR", "Always zero"], "ans": "1", "marks": 1, "topic": "Revenue", "ok": "Correct: Price must fall on all units to sell more, so MR lies below AR.", "fb": "Price must fall on all units to sell more, so MR lies below AR. Review the Learn tab.", "model": "Below AR"}, {"id": "q2", "type": "mcq", "q": "Total revenue is at its maximum where:", "opts": ["MR = MC", "MR = 0", "AR = AC", "MC = AC"], "ans": "1", "marks": 1, "topic": "Revenue", "ok": "Correct: When MR is zero, extra sales add nothing to revenue.", "fb": "When MR is zero, extra sales add nothing to revenue. Review the Learn tab.", "model": "MR = 0"}, {"id": "q3", "type": "mcq", "q": "Profit is maximised where:", "opts": ["MR = 0", "MC = MR", "AR = AC", "MC = AC"], "ans": "1", "marks": 1, "topic": "Profit", "ok": "Correct: MC = MR.", "fb": "MC = MR. Review the Learn tab.", "model": "MC = MR"}, {"id": "q4", "type": "mcq", "q": "Where MR is positive, demand is:", "opts": ["Price elastic", "Price inelastic", "Unit elastic", "Perfectly inelastic"], "ans": "0", "marks": 1, "topic": "Revenue and PED", "ok": "Correct: A price cut raises revenue only if demand is elastic.", "fb": "A price cut raises revenue only if demand is elastic. Review the Learn tab.", "model": "Price elastic"}, {"id": "q5", "type": "mcq", "q": "MC cuts AC:", "opts": ["At its maximum", "At its minimum", "At any point", "Never"], "ans": "1", "marks": 1, "topic": "Costs", "ok": "Correct: MC passes through the minimum of AC.", "fb": "MC passes through the minimum of AC. Review the Learn tab.", "model": "At its minimum"}, {"id": "q6", "type": "mcq", "q": "Normal profit occurs where:", "opts": ["AR > AC", "AR = AC", "AR < AC", "MR = MC"], "ans": "1", "marks": 1, "topic": "Profit", "ok": "Correct: Normal profit is the minimum to keep the firm in the industry.", "fb": "Normal profit is the minimum to keep the firm in the industry. Review the Learn tab.", "model": "AR = AC"}, {"id": "q7", "type": "mcq", "q": "Sales maximisation (with no loss) occurs where:", "opts": ["MR = 0", "MC = MR", "AR = AC", "MC = AC"], "ans": "2", "marks": 1, "topic": "Objectives", "ok": "Correct: Output is pushed as far as AR = AC.", "fb": "Output is pushed as far as AR = AC. Review the Learn tab.", "model": "AR = AC"}, {"id": "q8", "type": "num", "q": "A firm sells 40 units at £15 each. Calculate total revenue (£).", "ans": 600, "tol": 0.1, "marks": 1, "topic": "Revenue", "hint": "Enter a number.", "ok": "Correct: TR = P × Q = 15 × 40 = £600.", "fb": "TR = P × Q = 15 × 40 = £600. Check the worked examples.", "model": "600"}, {"id": "q9", "type": "num", "q": "Total cost is £480 for 40 units. Calculate average cost (£).", "ans": 12, "tol": 0.01, "marks": 1, "topic": "Costs", "hint": "Enter a number.", "ok": "Correct: AC = TC ÷ Q = 480 ÷ 40 = £12.", "fb": "AC = TC ÷ Q = 480 ÷ 40 = £12. Check the worked examples.", "model": "12"}, {"id": "q10", "type": "num", "q": "TR rises from £600 to £660 when output rises from 40 to 44 units. Calculate marginal revenue (£).", "ans": 15, "tol": 0.01, "marks": 1, "topic": "Revenue", "hint": "Enter a number.", "ok": "Correct: MR = ΔTR ÷ ΔQ = 60 ÷ 4 = £15.", "fb": "MR = ΔTR ÷ ΔQ = 60 ÷ 4 = £15. Check the worked examples.", "model": "15"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();
